-- 002_seed_demo_practitioners.sql
-- Demo doctors, weekly schedules, demo emails (reserved example.org domain) and facility illustrations.
-- Every practitioner is flagged is_demo = true with a visible demo_label. Idempotent: safe to re-run.
-- Requires 001 first, and the files in public/images/ copied into your Next.js public/ folder.
do $seed$
declare v_src uuid;
begin
  select id into v_src from public.data_sources where url = 'https://github.com/sabyasachi69/SwasthyaPath' and evidence_type = 'demo_synthetic' limit 1;
  if v_src is null then
    insert into public.data_sources (url, owner, evidence_type, public_note)
    values ('https://github.com/sabyasachi69/SwasthyaPath', 'SwasthyaPath project', 'demo_synthetic',
            'Synthetic demonstration profiles generated for the project. Not real clinicians, schedules or contact details.')
    returning id into v_src;
  end if;

  insert into public.facility_practitioners
    (id, facility_id, display_name, specialization, qualification, source_id, verified_at, valid_until, published,
     is_demo, demo_label, department_group, sub_specialty, designation, gender, experience_years, languages, consultation_fee_inr, photo_path)
  select r.id, f.id, r.display_name, r.specialization, r.qualification, v_src, now(), now() + interval '365 days', true,
         true, 'Demo profile - not a real clinician', r.department_group, r.sub_specialty, r.designation, r.gender, r.experience_years, r.languages, r.consultation_fee_inr, r.photo_path
