       as r(id uuid, facility_slug text, display_name text, specialization text, department_group text, sub_specialty text, designation text,
            qualification text, gender text, experience_years int, languages text[], consultation_fee_inr int, photo_path text, email text)
  join public.facilities f on f.slug = r.facility_slug
  on conflict (id) do nothing;

