  from jsonb_to_recordset($json$[{"facility_slug":"aiims-bhubaneswar","public_path":"/images/facilities/aiims-bhubaneswar.svg","alt_text":"Illustration of AIIMS Bhubaneswar (hospital) - demo image, not a photograph"},{"facility_slug":"apollo-hospitals-bhubaneswar","public_path":"/images/facilities/apollo-hospitals-bhubaneswar.svg","alt_text":"Illustration of Apollo Hospitals Bhubaneswar (hospital) - demo image, not a photograph"},{"facility_slug":"capital-hospital-pgimer-and-capital-hospital","public_path":"/images/facilities/capital-hospital-pgimer-and-capital-hospital.svg","alt_text":"Illustration of Capital Hospital (PGIMER and Capital Hospital) (hospital) - demo image, not a photograph"},{"facility_slug":"care-hospitals-bhubaneswar","public_path":"/images/facilities/care-hospitals-bhubaneswar.svg","alt_text":"Illustration of CARE Hospitals Bhubaneswar (hospital) - demo image, not a photograph"},{"facility_slug":"ims-sum-hospital","public_path":"/images/facilities/ims-sum-hospital.svg","alt_text":"Illustration of IMS & SUM Hospital (hospital) - demo image, not a photograph"},{"facility_slug":"kalinga-hospital","public_path":"/images/facilities/kalinga-hospital.svg","alt_text":"Illustration of Kalinga Hospital (hospital) - demo image, not a photograph"},{"facility_slug":"kims-bhubaneswar-kalinga-institute-of-medical-sciences","public_path":"/images/facilities/kims-bhubaneswar-kalinga-institute-of-medical-sciences.svg","alt_text":"Illustration of KIMS Bhubaneswar (Kalinga Institute of Medical Sciences) (hospital) - demo image, not a photograph"},{"facility_slug":"manipal-hospitals-bhubaneswar","public_path":"/images/facilities/manipal-hospitals-bhubaneswar.svg","alt_text":"Illustration of Manipal Hospitals Bhubaneswar (hospital) - demo image, not a photograph"},{"facility_slug":"utkal-hospital","public_path":"/images/facilities/utkal-hospital.svg","alt_text":"Illustration of Utkal Hospital (hospital) - demo image, not a photograph"},{"facility_slug":"kar-clinic-hos